```javascript
function draw() {
  if (gameState !== 'PLAYING') {
    drawEnvironment();
    return;
  }

  frames++;
  if (frames % 10 === 0) {
    score += 1; 
  }

  if (keyIsDown(32)) {
    player.vy -= 1.2;
  }
  player.vy += 0.6;
  player.vy = constrain(player.vy, -8, 8);
  player.y += player.vy;

  if (player.y < 20) {
    player.y = 20;
    if (player.vy < 0) player.vy = 0;
  }
  if (player.y + player.h > 380) {
    player.y = 380 - player.h;
    if (player.vy > 0) player.vy = 0;
  }

  distance += scrollSpeed;
  if (distance > nextSpawnDist) {
    spawnEntities();
  }

  for (let i = coins.length - 1; i >= 0; i--) {
    coins[i].x -= scrollSpeed;
    if (rectCollide(player, coins[i])) {
      score += 10;
      coins.splice(i, 1);
      continue;
    }
    if (coins[i].x < -50) coins.splice(i, 1);
  }

  for (let i = zappers.length - 1; i >= 0; i--) {
    zappers[i].x -= scrollSpeed;

    let hitbox = {
      x: zappers[i].x + 3,
      y: zappers[i].y + 3,
      w: zappers[i].w - 6,
      h: zappers[i].h - 6
    };

    if (rectCollide(player, hitbox)) {
      lives = 0;
      gameState = 'GAMEOVER';
    }
    if (zappers[i].x < -300) zappers.splice(i, 1);
  }

  drawEnvironment();
}
```

